#ifdef NDEBUG
#undef NDEBUG
#endif
#include <cassert>
#include "include/cef_api_hash.h"
#include "network_controls.h"
using Controls=suitecut::NetworkControls;using Dict=Controls::Dict;
Dict Parse(const char*text){return CefParseJSON(text,JSON_PARSER_RFC)->GetDictionary();}
int main(){
  assert(cef_api_hash(CEF_API_VERSION,0));std::vector<std::pair<std::string,Dict>>sent;std::vector<Controls::Result>ack;std::vector<Dict>events;std::vector<uint64_t>bodies;std::vector<uint8_t>published;
  Controls controls([&](const std::string&,const std::string&method,Dict params,Controls::Result done){if(method=="Fetch.fulfillRequest"||method=="Fetch.failRequest"||method=="Fetch.continueRequest"){sent.emplace_back(method,params->Copy(false));ack.push_back(std::move(done));}else done(true,"");},[&](Dict value){events.push_back(value->Copy(false));},[](const std::string&){assert(false);},[]{},[]{return 10;},[&](uint64_t id,size_t,size_t,std::span<const uint8_t> bytes,bool canceled){assert(!canceled);bodies.push_back(id);published.insert(published.end(),bytes.begin(),bytes.end());return true;});
  auto replay=std::make_shared<suitecut::NativeHARReplay>();std::string error;assert(replay->Load(Parse(R"({"log":{"entries":[{"request":{"url":"https://native.test/binary","method":"POST","headers":[],"postData":{"text":"AP8=","_encoding":"base64"}},"response":{"status":201,"statusText":"Created","headers":[{"name":"Set-Cookie","value":"a=1"},{"name":"Set-Cookie","value":"b=2"},{"name":"Content-Encoding","value":"gzip"}],"content":{"text":"AP8NCg==","encoding":"base64"}}}]}})"),error));bool installed=false;assert(controls.BindReplay("native-har","**",replay,false,[&](bool ok,const std::string&){assert(ok);installed=true;}));assert(installed);
  auto pause=Parse(R"({"requestId":"actual-fetch1","networkId":"native-request1","frameId":"frame1","resourceType":"Fetch","request":{"url":"https://native.test/binary","method":"POST","headers":{},"postDataEntries":[{"bytes":"AP8="}]}})");controls.Event("Fetch.requestPaused",pause,"");assert(events.empty()&&sent.size()==1&&sent.back().first=="Fetch.fulfillRequest");auto actual=sent.back().second;assert(actual->GetInt("responseCode")==201&&actual->GetString("body")=="AP8NCg==");auto headers=actual->GetList("responseHeaders");int cookies=0;for(size_t i=0;i<headers->GetSize();++i){auto h=headers->GetDictionary(i);assert(h->GetString("name")!="Content-Encoding");if(h->GetString("name")=="Set-Cookie")++cookies;}assert(cookies==2);auto diagnostics=CefDictionaryValue::Create();controls.Diagnostics(diagnostics);assert(diagnostics->GetInt("networkScopeRouteCallbacks")==0);assert(diagnostics->GetInt("networkBodyOwners")==0);assert(ack.size()==1);ack[0](true,"");
  // Native HAR fallback cooperates with actual ordinary route order, without
  // inventing a callback lease for replay or rematching an overridden URL.
  controls.UnbindReplay("native-har",[](bool ok,const std::string&){assert(ok);});auto register_route=Parse(R"({"action":"registerRoute","registrationId":"user-fallback","url":"**","times":0})");controls.Command(11,register_route,[](bool ok,const std::string&,const std::string&){assert(ok);});assert(controls.BindReplay("har-fallback","**",replay,true,[](bool ok,const std::string&){assert(ok);}));
  pause->SetString("requestId","actual-fetch2");pause->GetDictionary("request")->SetString("url","https://native.test/missing");controls.Event("Fetch.requestPaused",pause,"");assert(events.empty());controls.Tick(10);assert(bodies.size()==1&&published==std::vector<uint8_t>({0,255}));assert(controls.BodyAcknowledged(std::to_string(bodies[0]),"received"));assert(controls.BodyAcknowledged(std::to_string(bodies[0]),"taken"));assert(events.size()==1&&events.back()->GetString("event")=="route");auto route=events.back()->GetDictionary("route");assert(route->GetString("registrationId")=="user-fallback");auto resolve=CefDictionaryValue::Create();resolve->SetString("action","continue");resolve->SetString("routeId",route->GetString("id"));bool finished=false;controls.Command(12,resolve,[&](bool ok,const std::string&,const std::string&){assert(ok);finished=true;});assert(!finished&&sent.back().first=="Fetch.continueRequest");ack.back()(true,"");assert(finished);
  // Default notFound abort is genuine Fetch failure, with no fake response.
  controls.UnbindReplay("har-fallback",[](bool ok,const std::string&){assert(ok);});assert(controls.BindReplay("har-abort","**",replay,false,[](bool ok,const std::string&){assert(ok);}));pause->SetString("requestId","actual-fetch3");controls.Event("Fetch.requestPaused",pause,"");assert(sent.back().first=="Fetch.failRequest"&&sent.back().second->GetString("errorReason")=="Failed");ack.back()(true,"");controls.Clear();
}
